INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('majiayu000/claude-skill-registry/md2pdf', 'community', 'majiayu000', 'claude-skill-registry', 'majiayu000/claude-skill-registry', 'md2pdf', 0, 0, 45, '2026-02-18T01:08:43.517Z', '2026-02-18T13:09:20.773Z', NULL, '{"id":"majiayu000/claude-skill-registry/md2pdf","name":"md2pdf","description":{"zh":"该工具使用uv内联元数据，无需手动安装依赖项，即可轻松将Markdown转换为PDF","ja":"uv内联メタデータを使用するため、依存関係の手動インストールは不要です","ko":"uv 내장 메타데이터를 사용하여 종속성 수동 설치가 필요 없습니다","es":"Convierta Markdown a PDF con facilidad y personalice los estilos según sea necesario.","fr":"Convertissez Markdown en PDF facilement et personnalisez les styles selon vos besoins.","de":"Konvertieren Sie Markdown in PDF einfach und passen Sie die Stile nach Bedarf an.","pt":"O md2pdf é uma ferramenta para converter Markdown em PDF com suporte a fontes chinesas e estilização personalizável.","ru":"md2pdf - это инструмент для преобразования Markdown в PDF с поддержкой китайских шрифтов и настраиваемым стилем.","ar":"md2pdf هو أداة لتحويل ماركداون إلى بي دي إف مع دعم للخطوط الصينية وتخصيص الأسلوب.","en":"The most comprehensive Claude Code skills registry | Web Search: https://skills-registry-web.vercel.app"},"seo":{"title":{"zh":"Markdown转PDF工具","ja":"MarkdownをPDFに変換","ko":"Markdown를 PDF로 변환","es":"Conversor de Markdown a PDF","fr":"Convertisseur Markdown en PDF","de":"Markdown zu PDF Konverter","pt":"Conversor Markdown para PDF","ru":"Преобразователь Markdown в PDF","ar":"مُحَوِّل ماركداون إلى بي دي إف","en":"md2pdf"},"description":{"zh":"该工具使用uv内联元数据，无需手动安装依赖项，即可轻松将Markdown转换为PDF","ja":"uv内联メタデータを使用するため、依存関係の手動インストールは不要です","ko":"uv 내장 메타데이터를 사용하여 종속성 수동 설치가 필요 없습니다","es":"Convierta Markdown a PDF con facilidad y personalice los estilos según sea necesario.","fr":"Convertissez Markdown en PDF facilement et personnalisez les styles selon vos besoins.","de":"Konvertieren Sie Markdown in PDF einfach und passen Sie die Stile nach Bedarf an.","pt":"O md2pdf é uma ferramenta para converter Markdown em PDF com suporte a fontes chinesas e estilização personalizável.","ru":"md2pdf - это инструмент для преобразования Markdown в PDF с поддержкой китайских шрифтов и настраиваемым стилем.","ar":"md2pdf هو أداة لتحويل ماركداون إلى بي دي إف مع دعم للخطوط الصينية وتخصيص الأسلوب.","en":"The most comprehensive Claude Code skills registry | Web Search: https://skills-registry-web.vercel.app"},"definition":{"en":"The most comprehensive Claude Code skills registry | Web Search: https://skills-registry-web.vercel.app"},"features":{"zh":["支持中文字体","自定义样式","自动安装依赖项","命令行工具","支持自定义标题"],"ja":["中国語フォントのサポート","カスタムスタイル","依存関係の自動インストール","コマンドラインツール","カスタムタイトルのサポート"],"ko":["중국어 글꼴 지원","사용자 지정 스타일","종속성 자동 설치","명령줄 도구","사용자 지정 제목 지원"],"es":["Soporte de fuente china","Estilos personalizables","Conversión rápida y sencilla","Compatibilidad con metadatos en línea","Opción para agregar títulos personalizados"],"fr":["Prise en charge de la police chinoise","Styles personnalisables","Conversion rapide et simple","Compatibilité avec les métadonnées en ligne","Option pour ajouter des titres personnalisés"],"de":["Chinesische Schriftunterstützung","Anpassbare Stile","Schnelle und einfache Konvertierung","Kompatibilität mit Online-Metadaten","Option zum Hinzufügen von benutzerdefinierten Titeln"],"pt":["Suporte a fontes chinesas","Estilização personalizável","Conversão rápida e fácil","Suporte a CSS personalizado","Opção de título personalizado"],"ru":["Поддержка китайских шрифтов","Настройка стиля","Быстрое и простое преобразование","Поддержка пользовательского CSS","Возможность настройки заголовка"],"ar":["دعم للخطوط الصينية","تخصيص الأسلوب","تحويل سريع وسهل","دعم لCSS مخصص","خيار عنوان مخصص"]},"keywords":{"zh":["Markdown转PDF","Markdown转换工具","PDF转换","中文字体支持","自定义样式","命令行工具"],"ja":["MarkdownをPDFに変換","Markdown変換ツール","PDF変換","中国語フォントのサポート","カスタムスタイル","コマンドラインツール"],"ko":["Markdown를 PDF로 변환","Markdown 변환 도구","PDF 변환","중국어 글꼴 지원","사용자 지정 스타일","명령줄 도구"],"es":["conversor de markdown a pdf","markdown a pdf","conversión de markdown","soporte de fuente china","estilos personalizables","desarrollo web"],"fr":["convertisseur markdown en pdf","markdown en pdf","conversion de markdown","prise en charge de la police chinoise","styles personnalisables","développement web"],"de":["markdown zu pdf konverter","markdown zu pdf","konvertierung von markdown","chinesische schriftunterstützung","anpassbare stile","webentwicklung"],"pt":["conversor markdown para pdf","markdown para pdf","conversor de markdown","pdf com fontes chinesas","estilização personalizável","conversão de markdown"],"ru":["преобразователь markdown в pdf","markdown в pdf","преобразователь markdown","pdf с китайскими шрифтами","настраиваемый стиль","преобразование markdown"],"ar":["مُحَوِّل ماركداون إلى بي دي إف","ماركداون إلى بي دي إف","مُحَوِّل ماركداون","بي دي إف مع خطوط صينية","تخصيص الأسلوب","تحويل ماركداون"]}},"owner":"majiayu000","repo":"claude-skill-registry","repoPath":"majiayu000/claude-skill-registry","stars":0,"forks":0,"updatedAt":"2026-02-18T01:08:43.517Z","topics":[],"category":"community","skillMd":{"name":"md2pdf","description":"Convert Markdown files to beautifully styled PDFs with full Chinese font support. Use when: (1) Converting .md files to PDF format, (2) Creating printable documents from Markdown, (3) Generating book chapters or story PDFs, (4) Needing PDF output with custom styling (colors, fonts, backgrounds), (5) Working with Chinese text that needs proper rendering in PDF.","bodyPreview":"# Markdown to PDF Converter\n\nConvert Markdown to PDF with Chinese font support and customizable styling.\n\n## Quick Start\n\nThe script uses uv inline metadata - no manual dependency installation needed:\n\n```bash\n# Basic conversion (uv auto-installs dependencies)\nuv run scripts/md2pdf.py input.md output.pdf\n\n# With custom CSS\nuv run scripts/md2pdf.py input.md output.pdf --style assets/vintage-paper.css\n\n# With custom title\nuv run scripts/md2pdf.py input.md output.pdf --title \"Chapter Title\"\n\n# Or m","body":"# Markdown to PDF Converter\n\nConvert Markdown to PDF with Chinese font support and customizable styling.\n\n## Quick Start\n\nThe script uses uv inline metadata - no manual dependency installation needed:\n\n```bash\n# Basic conversion (uv auto-installs dependencies)\nuv run scripts/md2pdf.py input.md output.pdf\n\n# With custom CSS\nuv run scripts/md2pdf.py input.md output.pdf --style assets/vintage-paper.css\n\n# With custom title\nuv run scripts/md2pdf.py input.md output.pdf --title \"Chapter Title\"\n\n# Or make executable and run directly\nchmod +x scripts/md2pdf.py\n./scripts/md2pdf.py input.md output.pdf\n```\n\n> **Note**: On macOS, the script automatically configures Homebrew library paths.\n\n## Available Styles\n\nTwo pre-built styles in `assets/`:\n\n| Style | File | Description |\n|-------|------|-------------|\n| Vintage Paper | `vintage-paper.css` | Warm cream background, brown text, serif fonts. Ideal for stories and literature. |\n| Modern Clean | `modern-clean.css` | White background, dark text, sans-serif fonts. Ideal for technical documents. |\n\n## Default Style Features\n\nThe built-in default style (vintage paper) includes:\n- **Background**: Warm cream (#FAF6F0)\n- **Text color**: Dark brown (#4A3728)\n- **Heading color**: Darker brown (#3D2B1F)\n- **Font**: Chinese serif (Noto Serif SC, Songti SC)\n- **Line height**: 1.8\n- **Paragraph indent**: 2em (Chinese style)\n- **Page footer**: Page numbers\n\n## Customization\n\nTo customize styling, copy an existing CSS file and modify:\n\n```css\n@page {\n    size: A4;                        /* Paper size */\n    margin: 2.5cm 2cm;               /* Page margins */\n    background-color: #FAF6F0;       /* Page background */\n}\n\nbody {\n    font-family: \"Noto Serif SC\", serif;  /* Font stack */\n    font-size: 12pt;                      /* Base font size */\n    line-height: 1.8;                     /* Line spacing */\n    color: #4A3728;                       /* Text color */\n}\n```\n\n### Chinese Font Priority\n\nThe converter uses this font fallback chain:\n1. Noto Serif SC (Google Noto fonts)\n2. Source Han Serif SC (Adobe fonts)\n3. Songti SC (macOS)\n4. STSong (macOS)\n5. SimSun (Windows)\n\nEnsure at least one of these fonts is installed on the system.\n\n## Script API\n\n```python\nfrom md2pdf import convert_md_to_pdf\n\nconvert_md_to_pdf(\n    input_path=\"chapter.md\",\n    output_path=\"chapter.pdf\",\n    custom_css=\"assets/vintage-paper.css\",  # Optional\n    title=\"Chapter 1\"                        # Optional\n)\n```\n\n## Troubleshooting\n\n### WeasyPrint system dependencies\n```bash\n# macOS (library path is auto-configured by script)\nbrew install pango\n\n# Ubuntu/Debian\nsudo apt install libpango-1.0-0 libpangocairo-1.0-0\n```\n\n### Missing Chinese fonts\n```bash\n# macOS\nbrew install font-noto-serif-cjk-sc\n\n# Ubuntu/Debian\nsudo apt install fonts-noto-cjk\n```\n"},"lastSynced":"2026-02-18T13:09:20.773Z","agentAnalysis":{"suitability":{"en":"Perfect for Document Analysis Agents needing Markdown to PDF conversion with customizable styling and Chinese font support.","zh":"非常适合需要将Markdown转换为PDF并支持自定义样式和中文字体的文档分析代理。","ja":"MarkdownをPDFに変換し、カスタマイズ可能なスタイリングと中国語フォントのサポートが必要なドキュメント分析エージェントに最適です。","ko":"Markdown를 PDF로 변환하고, 사용자 정의 스타일링과 중국어 폰트 지원이 필요한 문서 분석 에이전트에 적합합니다.","es":"Perfecto para agentes de Análisis de Documentos que necesitan conversión de Markdown a PDF con estilo personalizable y soporte para fuentes chinas.","fr":"Parfait pour les agents d''Analyse de Documents nécessitant une conversion de Markdown en PDF avec un style personnalisable et un support de polices chinoises.","de":"Perfekt für Dokumentenanalyse-Agents, die eine Markdown-zu-PDF-Konvertierung mit anpassbarem Stil und chinesischer Schriftunterstützung benötigen.","pt":"Perfeito para Agentes de Análise de Documentos que necessitam de conversão de Markdown para PDF com estilização personalizável e suporte a fontes chinesas.","ru":"Идеально подходит для агентов анализа документов, которым требуется преобразование Markdown в PDF с настраиваемым стилем и поддержкой китайских шрифтов.","ar":"مثالي لعميل تحليل الوثائق الذي يحتاج إلى تحويل Markdown إلى PDF مع أسلوب قابل للتعديل ودعم لخطوط الصين"},"recommendation":{"en":"Empowers agents to convert Markdown files to PDFs with custom CSS styling and metadata like titles, leveraging uv inline metadata for seamless dependency management and supporting various Markdown formats.","zh":"赋予代理转换Markdown文件为PDF的能力，支持自定义CSS样式和元数据，如标题，并利用uv内联元数据实现无缝的依赖管理，支持多种Markdown格式。","ja":"エージェントがMarkdownファイルをPDFに変換する能力を提供し、カスタマイズ可能なCSSスタイリングとメタデータ（タイトルなど）をサポートし、uv内联メタデータを使用して依存関係管理をシームレスに行い、さまざまなMarkdown形式をサポートします。","ko":"에이전트가 Markdown 파일을 PDF로 변환할 수 있는 기능을 제공하며, 사용자 정의 CSS 스타일링과 메타데이터(제목 등)를 지원하며, uv 내联 메타데이터를 사용하여 무결점의 의존성 관리를 수행하고, 다양한 마크다운 형식을 지원합니다.","es":"Habilita a los agentes a convertir archivos Markdown a PDF con estilo de CSS personalizado y metadatos como títulos, aprovechando los metadatos en línea de uv para una gestión de dependencias sin problemas y admitiendo varios formatos de Markdown.","fr":"Permet aux agents de convertir des fichiers Markdown en PDF avec un style CSS personnalisé et des métadonnées comme des titres, en exploitant les métadonnées en ligne de uv pour une gestion de dépendances transparente et en prenant en charge différents formats de Markdown.","de":"Ermöglicht es Agents, Markdown-Dateien in PDFs mit benutzerdefiniertem CSS-Stil und Metadaten wie Titeln zu konvertieren, indem es die Inline-Metadaten von uv für eine nahtlose Abhängigkeitsverwaltung nutzt und verschiedene Markdown-Formate unterstützt.","pt":"Habilita os agentes a converter arquivos Markdown em PDFs com estilização CSS personalizada e metadados como títulos, aproveitando metadados uv inline para gerenciamento de dependências sem problemas e suportando vários formatos Markdown.","ru":"Наделяет агентов возможностью конвертировать файлы Markdown в PDF с настраиваемым стилем CSS и метаданными, такими как названия, используя метаданные uv inline для беспроблемного управления зависимостями и поддержки различных форматов Markdown.","ar":"يمنح الوكلاء khảية تحويل ملفات Markdown إلى PDF مع أسلوب CSS قابل للتعديل وبيانات وصفية مثل العناوين، مستفيداً من بيانات uv المتضمنة لادارة الاعتماد بدون مشاكل ودعم صيغ Markdown المختلفة"},"useCases":{"en":["Converting Markdown documentation to PDF for distribution","Generating reports in PDF format from Markdown data","Creating styled PDFs from Markdown files with custom titles and fonts"],"zh":["将Markdown文档转换为PDF以进行分发","从Markdown数据生成PDF格式的报告","使用自定义标题和字体从Markdown文件创建样式化的PDF"],"ja":["MarkdownドキュメントをPDFに変換して配布する","MarkdownデータからPDF形式のレポートを生成する","カスタマイズ可能なタイトルとフォントを使用してMarkdownファイルからスタイリングされたPDFを作成する"],"ko":["Markdown 문서를 PDF로 변환하여 배포하기","Markdown 데이터에서 PDF 형식의 보고서를 생성하기","사용자 정의 제목과 글꼴을 사용하여 Markdown 파일에서 스타일이 지정된 PDF를 생성하기"],"es":["Convertir documentación de Markdown a PDF para distribución","Generar informes en formato PDF a partir de datos de Markdown","Crear PDF con estilo a partir de archivos de Markdown con títulos y fuentes personalizadas"],"fr":["Convertir la documentation Markdown en PDF pour distribution","Générer des rapports au format PDF à partir de données Markdown","Créer des PDF avec style à partir de fichiers Markdown avec des titres et des polices personnalisés"],"de":["Markdown-Dokumentation in PDF für Verteilung umwandeln","Berichte im PDF-Format aus Markdown-Daten generieren","Gestaltete PDFs aus Markdown-Dateien mit benutzerdefinierten Titeln und Schriftarten erstellen"],"pt":["Conversão de documentação Markdown em PDF para distribuição","Geração de relatórios em formato PDF a partir de dados Markdown","Criação de PDFs estilizados a partir de arquivos Markdown com títulos e fontes personalizadas"],"ru":["Преобразование документации Markdown в PDF для распространения","Генерация отчетов в формате PDF из данных Markdown","Создание стилей PDF из файлов Markdown с настраиваемыми заголовками и шрифтами"],"ar":["تحويل توثيق Markdown إلى PDF للانتشار","توليد تقارير بالصيغة PDF من بيانات Markdown","إنشاء PDFs مطبوعة من ملفات Markdown مع عناوين وخطوط قابلة للتعديل"]},"limitations":{"en":["Requires uv for dependency management","Limited to Markdown input format","Customization limited to CSS styling and title metadata"],"zh":["需要uv进行依赖管理","仅限Markdown输入格式","自定义仅限于CSS样式和标题元数据"],"ja":["依存関係管理にuvが必要","入力形式はMarkdownのみ","カスタマイズはCSSスタイリングとタイトルメタデータのみ"],"ko":["의존성 관리를 위해 uv가 필요함","입력 형식은 Markdown만 지원함","사용자 정의는 CSS 스타일링과 제목 메타데이터만 지원함"],"es":["Requiere uv para la gestión de dependencias","Limitado al formato de entrada de Markdown","Personalización limitada al estilo de CSS y metadatos de título"],"fr":["Nécessite uv pour la gestion de dépendances","Limité au format d''entrée Markdown","Personnalisation limitée au style CSS et aux métadonnées de titre"],"de":["Benötigt uv für die Abhängigkeitsverwaltung","Begrenzt auf Markdown-Eingabeformat","Anpassung beschränkt auf CSS-Stil und Titelmetadaten"],"pt":["Requer uv para gerenciamento de dependências","Limitado ao formato de entrada Markdown","Personalização limitada ao estilização CSS e metadados de título"],"ru":["Требуется uv для управления зависимостями","Ограничен входным форматом Markdown","Настройка ограничена стилем CSS и метаданными названия"],"ar":["يتطلب uv لإدارة الاعتماد","محدود بصيغة المدخلات Markdown","التخصيص مقيد بأسلوب CSS وبيانات وصفية العنوان"]},"version":3},"qualityScore":45}');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('majiayu000/claude-skill-registry/office', 'community', 'majiayu000', 'claude-skill-registry', 'majiayu000/claude-skill-registry', 'office', 0, 0, 55, '2026-02-18T01:08:43.517Z', '2026-02-18T13:09:23.422Z', NULL, '{"id":"majiayu000/claude-skill-registry/office","name":"office","description":{"zh":"使用 TypeScript 生成 Microsoft Office 文档和 PDF。支持 docx、xlsx、pdf-lib 和 pptxgenjs 库","ja":"TypeScript を使用して Microsoft Office ドキュメントと PDF を生成します。docx、xlsx、pdf-lib、pptxgenjs ライブラリをサポート","ko":"TypeScript를 사용하여 Microsoft Office 문서와 PDF를 생성합니다. docx, xlsx, pdf-lib, pptxgenjs 라이브러리를 지원합니다","es":"La generación de documentos de Office con TypeScript permite crear documentos personalizados de forma eficiente. Utiliza bibliotecas de JavaScript puro para generar documentos de Office y PDF","fr":"La génération de documents Office avec TypeScript permet de créer des documents personnalisés de manière efficace. Utilisez des bibliothèques JavaScript pures pour générer des documents Office et des PDF","de":"Die Erstellung von Office-Dokumenten mit TypeScript ermöglicht die effiziente Erstellung von benutzerdefinierten Dokumenten. Verwenden Sie reine JavaScript-Bibliotheken, um Office-Dokumente und PDFs zu erstellen","pt":"Gere documentos Office com TypeScript e bibliotecas JavaScript puro. Suporte a docx, xlsx, pdf e pptx.","ru":"Создайте документы Office с помощью TypeScript и библиотек JavaScript. Поддержка docx, xlsx, pdf и pptx.","ar":"انشئ مستندات أوفيس باستخدام TypeScript و مكتبات JavaScript النقية. دعم docx و xlsx و pdf و pptx.","en":"The most comprehensive Claude Code skills registry | Web Search: https://skills-registry-web.vercel.app"},"seo":{"title":{"zh":"Office 文档生成 - 使用 TypeScript 编程","ja":"Office ドキュメント生成 - TypeScript を使用","ko":"Office 문서 생성 - TypeScript 사용","es":"Generación de documentos de Office con TypeScript","fr":"G