INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('podverse/podverse/podverse-orm-patterns', 'community', 'podverse', 'podverse', 'podverse/podverse', 'podverse-orm-patterns', 0, 0, 50, '2026-02-18T01:08:43.520Z', '2026-02-18T13:26:27.564Z', NULL, '{"id":"podverse/podverse/podverse-orm-patterns","name":"podverse-orm-patterns","description":{"zh":"Podverse ORM ","ja":"Podverse ORM","ko":"Podverse ORM ","es":"El paquete Podverse ORM ofrece patrones de desarrollo para mejorar la infraestructura y los módulos de las aplicaciones","fr":"Le package Podverse ORM propose des modèles de développement pour améliorer l''infrastructure et les modules des applications","de":"Das Podverse-ORM-Paket bietet Entwicklungsmuster, um die Infrastruktur und Module von Anwendungen zu verbessern","pt":"O Podverse ORM é um pacote de infraestrutura para desenvolvimento de aplicações. Fornece padrões e ferramentas para simplificar o processo de desenvolvimento","ru":"Podverse ORM - это пакет инфраструктуры для разработки приложений. Предоставляет шаблоны и инструменты для упрощения процесса разработки","ar":"Podverse ORM هو حزمة بنية تحتية لتطوير التطبيقات. يوفر نماذج وأدوات لتبسيط عملية التطوير","en":"Podverse monorepo for all infrastructure, modules, applications, and deployments"},"seo":{"title":{"zh":"Podverse ORM ","ja":"Podverse ORM","ko":"Podverse ORM ","es":"Patrones de desarrollo ORM de Podverse","fr":"Modèles de développement ORM de Podverse","de":"Podverse-ORM-Entwicklungsmuster","pt":"Padrões de Desenvolvimento Podverse ORM","ru":"Шаблоны разработки Podverse ORM","ar":"نماذج تطوير Podverse ORM","en":"podverse-orm-patterns"},"description":{"zh":"Podverse ORM ","ja":"Podverse ORM","ko":"Podverse ORM ","es":"El paquete Podverse ORM ofrece patrones de desarrollo para mejorar la infraestructura y los módulos de las aplicaciones","fr":"Le package Podverse ORM propose des modèles de développement pour améliorer l''infrastructure et les modules des applications","de":"Das Podverse-ORM-Paket bietet Entwicklungsmuster, um die Infrastruktur und Module von Anwendungen zu verbessern","pt":"O Podverse ORM é um pacote de infraestrutura para desenvolvimento de aplicações. Fornece padrões e ferramentas para simplificar o processo de desenvolvimento","ru":"Podverse ORM - это пакет инфраструктуры для разработки приложений. Предоставляет шаблоны и инструменты для упрощения процесса разработки","ar":"Podverse ORM هو حزمة بنية تحتية لتطوير التطبيقات. يوفر نماذج وأدوات لتبسيط عملية التطوير","en":"Podverse monorepo for all infrastructure, modules, applications, and deployments"},"definition":{"en":"Podverse monorepo for all infrastructure, modules, applications, and deployments"},"features":{"zh":["Podverse ","ORM","Monorepo","Database","Helper"],"ja":["Podverse ","ORM","Monorepo","Database","Helper"],"ko":["Podverse ","ORM","Monorepo","Database","Helper"],"es":["Mejora de la infraestructura de las aplicaciones","Optimización de los módulos y paquetes","Implementación de migraciones de bases de datos","Uso de paquetes de ayuda para la validación y configuración","Desarrollo de patrones de diseño de bases de datos"],"fr":["Amélioration de l''infrastructure des applications","Optimisation des modules et paquets","Mise en œuvre de migrations de bases de données","Utilisation de paquets d''aide pour la validation et la configuration","Développement de modèles de conception de bases de données"],"de":["Verbesserung der Infrastruktur von Anwendungen","Optimierung von Modulen und Paketen","Implementierung von Datenbankmigrationen","Verwendung von Hilfspaketen für Validierung und Konfiguration","Entwicklung von Datenbankdesignmustern"],"pt":["Padrões de desenvolvimento de infraestrutura","Gerenciamento de migrações de banco de dados","Integração com pacotes de ajuda","Suporte a deploy de aplicações","Documentação técnica detalhada"],"ru":["Шаблоны разработки инфраструктуры","Управление миграциями базы данных","Интеграция с пакетами помощи","Поддержка deploy приложений","Детальная техническая документация"],"ar":["نماذج تطوير البنية التحتية","إدارة هجرات قاعدة البيانات","تكامل مع حزم المساعدة","دعم نشر التطبيقات","وثائق فنية مفصلة"]},"keywords":{"zh":["Podverse ORM","Monorepo","Database","Helper","ORM","Podverse"],"ja":["Podverse ORM","Monorepo","Database","Helper","ORM","Podverse"],"ko":["Podverse ORM","Monorepo","Database","Helper","ORM","Podverse"],"es":["patrones de desarrollo ORM","Podverse ORM","desarrollo de aplicaciones","infraestructura de aplicaciones","módulos y paquetes","migraciones de bases de datos","validación y configuración"],"fr":["modèles de développement ORM","Podverse ORM","développement d''applications","infrastructure d''applications","modules et paquets","migrations de bases de données","validation et configuration"],"de":["Entwicklungsmuster ORM","Podverse ORM","Anwendungsentwicklung","Anwendungsinfrastruktur","Module und Pakete","Datenbankmigrationen","Validierung und Konfiguration"],"pt":["Podverse ORM","Desenvolvimento de aplicações","Infraestrutura de desenvolvimento","Gerenciamento de banco de dados","Deploy de aplicações","Padrões de desenvolvimento"],"ru":["Podverse ORM","Разработка приложений","Инфраструктура разработки","Управление базой данных","Deploy приложений","Шаблоны разработки"],"ar":["Podverse ORM","تطوير التطبيقات","بنية تحتية للتطوير","إدارة قاعدة البيانات","نشر التطبيقات","نماذج التطوير"]}},"owner":"podverse","repo":"podverse","repoPath":"podverse/podverse","stars":0,"forks":0,"updatedAt":"2026-02-18T01:08:43.520Z","topics":[],"category":"community","skillMd":{"name":"podverse-orm-patterns","description":"Common patterns for the podverse-orm package","version":"1.0.0","bodyPreview":"# Podverse ORM Development Patterns\n\nThis skill provides quick reference for common patterns used in the podverse-orm package.\n\n## Monorepo Context\n\n- **ORM package location**: `packages/orm/`\n- **Database migrations**: `infra/database/main/migrations/`\n- **Helper packages** (from `packages/helpers*/`): `@podverse/helpers`, `@podverse/helpers-validation`, `@podverse/helpers-config`\n\n## Key Dependencies\n\n| Package         | Purpose                         |\n| --------------- | -------------------","body":"# Podverse ORM Development Patterns\n\nThis skill provides quick reference for common patterns used in the podverse-orm package.\n\n## Monorepo Context\n\n- **ORM package location**: `packages/orm/`\n- **Database migrations**: `infra/database/main/migrations/`\n- **Helper packages** (from `packages/helpers*/`): `@podverse/helpers`, `@podverse/helpers-validation`, `@podverse/helpers-config`\n\n## Key Dependencies\n\n| Package         | Purpose                         |\n| --------------- | ------------------------------- |\n| Helper packages | Types, DTOs, validation, config |\n| `typeorm`       | ORM framework                   |\n\n## Patterns\n\n### Entity Definition\n\n```typescript\n// packages/orm/src/entities/Podcast.ts\nimport {\n  Entity,\n  PrimaryGeneratedColumn,\n  Column,\n  OneToMany,\n  CreateDateColumn,\n  UpdateDateColumn,\n} from ''typeorm'';\nimport { Episode } from ''./Episode'';\n\n@Entity(''podcast'')\nexport class Podcast {\n  @PrimaryGeneratedColumn(''uuid'')\n  id: string;\n\n  @Column()\n  title: string;\n\n  @Column({ nullable: true })\n  description?: string;\n\n  @Column({ unique: true })\n  feedUrl: string;\n\n  @Column({ nullable: true })\n  imageUrl?: string;\n\n  @OneToMany(() => Episode, (episode) => episode.podcast)\n  episodes: Episode[];\n\n  @CreateDateColumn()\n  createdAt: Date;\n\n  @UpdateDateColumn()\n  updatedAt: Date;\n}\n```\n\n### Service Pattern\n\n```typescript\n// packages/orm/src/services/PodcastService.ts\nimport { getRepository } from ''typeorm'';\nimport { Podcast } from ''../entities/Podcast'';\n\nexport const PodcastService = {\n  async getById(id: string): Promise<Podcast | null> {\n    const repo = getRepository(Podcast);\n    return repo.findOne({ where: { id } });\n  },\n\n  async getByFeedUrl(feedUrl: string): Promise<Podcast | null> {\n    const repo = getRepository(Podcast);\n    return repo.findOne({ where: { feedUrl } });\n  },\n\n  async create(data: Partial<Podcast>): Promise<Podcast> {\n    const repo = getRepository(Podcast);\n    const podcast = repo.create(data);\n    return repo.save(podcast);\n  },\n\n  async update(id: string, data: Partial<Podcast>): Promise<Podcast | null> {\n    const repo = getRepository(Podcast);\n    await repo.update(id, data);\n    return this.getById(id);\n  },\n\n  async delete(id: string): Promise<void> {\n    const repo = getRepository(Podcast);\n    await repo.delete(id);\n  },\n};\n```\n\n### Query Builder Pattern\n\n```typescript\n// For complex queries\nasync findWithFilters(filters: PodcastFilters): Promise<Podcast[]> {\n  const repo = getRepository(Podcast)\n  const qb = repo.createQueryBuilder(''podcast'')\n\n  if (filters.searchTerm) {\n    qb.where(''podcast.title ILIKE :term'', { term: `%${filters.searchTerm}%` })\n  }\n\n  if (filters.category) {\n    qb.andWhere(''podcast.category = :category'', { category: filters.category })\n  }\n\n  qb.orderBy(''podcast.createdAt'', ''DESC'')\n    .skip(filters.offset || 0)\n    .take(filters.limit || 20)\n\n  return qb.getMany()\n}\n```\n\n### Relations Pattern\n\n```typescript\n// Loading relations\nasync getByIdWithEpisodes(id: string): Promise<Podcast | null> {\n  const repo = getRepository(Podcast)\n  return repo.findOne({\n    where: { id },\n    relations: [''episodes'']\n  })\n}\n\n// Eager vs Lazy loading\n@OneToMany(() => Episode, (episode) => episode.podcast, { eager: false })\nepisodes: Episode[]\n```\n\n## Migration Patterns\n\nMigrations are located in `infra/database/main/migrations/`.\n\n### Creating a Migration\n\n```bash\n# Generate migration from entity changes\nnpm run typeorm migration:generate -- -n MigrationName\n\n# Create empty migration\nnpm run typeorm migration:create -- -n MigrationName\n```\n\n### Migration Structure\n\n```typescript\n// infra/database/main/migrations/YYYYMMDDHHMMSS-AddPodcastCategory.ts\nimport { MigrationInterface, QueryRunner, TableColumn } from ''typeorm'';\n\nexport class AddPodcastCategory1234567890123 implements MigrationInterface {\n  public async up(queryRunner: QueryRunner): Promise<void> {\n    await queryRunner.addColumn(\n      ''podcast'',\n      new TableColumn({\n        name: ''category'',\n        type: ''varchar'',\n        isNullable: true,\n      })\n    );\n  }\n\n  public async down(queryRunner: QueryRunner): Promise<void> {\n    await queryRunner.dropColumn(''podcast'', ''category'');\n  }\n}\n```\n\n## File Structure\n\n```\npackages/orm/\n├── src/\n│   ├── entities/        # TypeORM entities\n│   ├── services/        # Data access services\n│   ├── subscribers/     # Entity subscribers\n│   └── index.ts         # Public exports\n├── package.json\n└── tsconfig.json\n\ninfra/database/main/\n├── migrations/          # TypeORM migrations\n└── seeds/               # Seed data (if any)\n```\n\n## Best Practices\n\n1. **Always use services**: Don''t access repositories directly from controllers\n2. **Use transactions**: For operations that modify multiple entities\n3. **Index properly**: Add indexes for frequently queried columns\n4. **Validate at entity level**: Use class-validator decorators when appropriate\n5. **Use DTOs**: Transform entities to DTOs before sending to clients\n\n## Related Skills\n\n- **[API Patterns](../api/SKILL.md)** - Using ORM in controllers\n- **[Global Patterns](../global/SKILL.md)** - Monorepo conventions\n"},"lastSynced":"2026-02-18T13:26:27.564Z","agentAnalysis":{"suitability":{"en":"Ideal for Infrastructure Agents managing complex monorepo projects with ORM dependencies","zh":"适用于管理复杂单体仓库项目且具有ORM依赖的基础设施代理","ja":"ORMの依存関係を伴う複雑なモノレポプロジェクトを管理するインフラストラクチャエージェントに最適","ko":"ORM 의존성을 가진 복잡한 모노레포 프로젝트를 관리하는 인프라 에이전트에 적합","es":"Ideal para agentes de infraestructura que gestionan proyectos monorepo complejos con dependencias de ORM","fr":"Idéal pour les agents d''infrastructure gérant des projets monorepo complexes avec des dépendances ORM","de":"Ideal für Infrastrukturagenten, die komplexe Monorepo-Projekte mit ORM-Abhängigkeiten verwalten","pt":"Ideal para agentes de infraestrutura que gerenciam projetos monorepo complexos com dependências de ORM","ru":"Идеально подходит для агентов инфраструктуры, управляющих сложными проектами monorepo с зависимостями ORM","ar":"مثالي لعميل البنية التحتية لإدارة مشاريع monorepo معقدة مع зависимости ORM"},"recommendation":{"en":"Empowers agents to navigate and utilize the podverse-orm package, leveraging key dependencies like database migrations and helper packages, while streamlining development with established patterns and monorepo context","zh":"赋予代理导航和利用podverse-orm包的能力，利用关键依赖项如数据库迁移和辅助包，同时通过建立模式和单体仓库上下文简化开发","ja":"エージェントがpodverse-ormパッケージをナビゲートして利用できるようにし、データベースマイグレーションやヘルパーパッケージなどの重要な依存関係を活用し、モノレポのコンテキストを確立して開発を簡素化する","ko":"에이전트가 podverse-orm 패키지를 탐색하고 이용할 수 있도록 하여 데이터베이스 마이그레이션 및 헬퍼 패키지와 같은 주요 의존 항목을 활용하며 모노레포 컨텍스트를 설정하여 개발을 간소화한다","es":"Permite a los agentes navegar y utilizar el paquete podverse-orm, aprovechando dependencias clave como migraciones de base de datos y paquetes de ayuda, mientras se simplifica el desarrollo con patrones establecidos y contexto de monorepo","fr":"Permet aux agents de naviguer et d''utiliser le paquet podverse-orm, en exploitant les dépendances clés comme les migrations de base de données et les paquets d''aide, tout en simplifiant le développement avec des modèles établis et un contexte de monorepo","de":"Ermöglicht es den Agenten, das Paket podverse-orm zu navigieren und zu nutzen, indem es Schlüsselabhängigkeiten wie Datenbankmigrationen und Hilfspakete nutzt, während die Entwicklung mit etablierten Mustern und Monorepo-Kontext vereinfacht wird","pt":"Habilita os agentes a navegar e utilizar o pacote podverse-orm, aproveitando dependências-chave como migrações de banco de dados e pacotes de ajuda, enquanto simplifica o desenvolvimento com padrões estabelecidos e contexto de monorepo","ru":"Наделяет агентов возможностью ориентироваться и использовать пакет podverse-orm, используя ключевые зависимости, такие как миграции баз данных и пакеты-помощники, а также оптимизируя разработку с помощью устоявшихся шаблонов и контекста monorepo","ar":"تمكين العميل من التنقل واستخدام حزمة podverse-orm، واستخدام الاعتمادات الرئيسية مثل هجرات قاعدة البيانات وحزم المساعدة، بينما يبسط التطوير مع الأنماط المثبتة وسِياق monorepo"},"useCases":{"en":["Implementing database migrations within the infra/database/main/migrations/ directory","Integrating helper packages such as @podverse/helpers and @podverse/helpers-validation","Developing applications with the podverse-orm package located at packages/orm/"],"zh":["在infra/database/main/migrations/目录中实现数据库迁移","集成诸如@podverse/helpers和@podverse/helpers-validation的辅助包","使用位于packages/orm/的podverse-orm包开发应用程序"],"ja":["infra/database/main/migrations/ディレクトリ内でデータベースマイグレーションを実装する","@podverse/helpersや@podverse/helpers-validationなどのヘルパーパッケージを統合する","packages/orm/に位置するpodverse-ormパッケージを使用してアプリケーションを開発する"],"ko":["infra/database/main/migrations/ 디렉토리 내에서 데이터베이스 마이그레이션을 구현한다","@podverse/helpers 및 @podverse/helpers-validation와 같은 헬퍼 패키지를 통합한다","packages/orm/에 위치한 podverse-orm 패키지를 사용하여 애플리케이션을 개발한다"],"es":["Implementar migraciones de base de datos dentro del directorio infra/database/main/migrations/","Integrar paquetes de ayuda como @podverse/helpers y @podverse/helpers-validation","Desarrollar aplicaciones con el paquete podverse-orm ubicado en packages/orm/"],"fr":["Mettre en œuvre des migrations de base de données dans le répertoire infra/database/main/migrations/","Intégrer des paquets d''aide tels que @podverse/helpers et @podverse/helpers-validation","Développer des applications avec le paquet podverse-orm situé à packages/orm/"],"de":["Implementierung von Datenbankmigrationen im Verzeichnis infra/database/main/migrations/","Integration von Hilfspaketen wie @podverse/helpers und @podverse/helpers-validation","Entwicklung von Anwendungen mit dem Paket podverse-orm unter packages/orm/"],"pt":["Implementação de migrações de banco de dados dentro do diretório infra/database/main/migrations/","Integração de pacotes de ajuda, como @podverse/helpers e @podverse/helpers-validation","Desenvolvimento de aplicações com o pacote podverse-orm localizado em packages/orm/"],"ru":["Реализация миграций баз данных внутри директории infra/database/main/migrations/","Интеграция пакетов-помощников, таких как @podverse/helpers и @podverse/helpers-validation","Разработка приложений с пакетом podverse-orm, расположенным в packages/orm/"],"ar":["تنفيذ هجرات قاعدة البيانات داخل الدليل infra/database/main/migrations/","دمج حزم المساعدة مثل @podverse/helpers و @podverse/helpers-validation","تطوير التطبيقات مع حزمة podverse-orm الموجودة في packages/orm/"]},"limitations":{"en":["Requires understanding of monorepo structure and ORM package location","Dependent on specific helper packages and database migration setup"],"zh":["需要理解单体仓库结构和ORM包位置","依赖于特定的辅助包和数据库迁移设置"],"ja":["モノレポ構造とORMパッケージの位置を理解する必要がある","特定のヘルパーパッケージとデータベースマイグレーションの設定に依存する"],"ko":["모노레포 구조와 ORM 패키지 위치를 이해해야 한다","특정 헬퍼 패키지 및 데이터베이스 마이그레이션 설정에 의존한다"],"es":["Requiere comprensión de la estructura de monorepo y la ubicación del paquete de ORM","Dependiente de paquetes de ayuda específicos y configuración de migración de base de datos"],"fr":["Nécessite une compréhension de la structure de monorepo et de l''emplacement du paquet ORM","Dépendant de paquets d''aide spécifiques et de la configuration de migration de base de données"],"de":["Benötigt Verständnis der Monorepo-Struktur und des Speicherorts des ORM-Pakets","Abhängig von bestimmten Hilfspaketen und Datenbank-Migrationskonfiguration"],"pt":["Exige compreensão da estrutura de monorepo e localização do pacote de ORM","Dependente de pacotes de a